/*
 * A298850  Expansion of Product_{k>=1} (1 + x^(k*(k+1)/2))^(k*(k+1)/2).
 * https://oeis.org/A298850
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = Coefficient of x^n in \prod_{k≥1} (1 +
 *            x^(k(k+1)/2))^(k(k+1)/2)
 * Range:     u8 n <= 18, u16 n <= 46, u32 n <= 53, u64 n <= 53, u128 n <= 53,
 *            big any n
 * Helpers:   binom
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by dynamic programming.  For every triangular number
   T = k(k+1)/2 ≤ n we convolve the current polynomial with (1 + x^T)^T.
   The coefficient of x^j in that factor is binomial(T, j).  We use the
   provided binom function for exact arithmetic and perform all
   intermediate products through 128‑bit intermediates when possible. */

#include <stdlib.h>
#include <string.h>
#include "../utils/binom.h"

#if defined(__SIZEOF_INT128__)
/* helper macro for 128‑bit multiplication and addition if available */
#define MUL128(a, b) ((seq_t)(((__int128)(a)) * (__int128)(b)))
#define ADD128(a, b) ((seq_t)(((__int128)(a)) + (__int128)(b)))
#else
/* fall back to 64‑bit operations; overflow is acceptable only when the
   result certainly fits in 64 bits (it does for n ≤ 10000). */
#define MUL128(a, b) ((seq_t)((a) * (b)))
#define ADD128(a, b) ((seq_t)((a) + (b)))
#endif

seq_t a(idx_t n)
{
    /* a(0) = 1 by definition */
    if (n == 0)
        return (seq_t)1;

    /* Allocate DP arrays */
    seq_t *dp      = (seq_t*)malloc((n + 1) * sizeof(seq_t));
    seq_t *newdp   = (seq_t*)malloc((n + 1) * sizeof(seq_t));
    if (!dp || !newdp) {
        /* Out of memory – unspecified behaviour */
        return (seq_t)0;
    }

    /* initialise dp[0] = 1, others 0 */
    memset(dp, 0, (n + 1) * sizeof(seq_t));
    dp[0] = (seq_t)1;

    for (idx_t k = 1; ; ++k) {
        /* triangular number T_k = k*(k+1)/2 (computed in idx_t) */
        idx_t T = k * (k + 1) / 2;
        if (T > n)
            break; /* factors larger than n have no influence */

        /* maximum multiplicity j for this factor */
        idx_t max_j = n / T;
        if (max_j > T)
            max_j = T;

        /* clear newdp */
        memset(newdp, 0, (n + 1) * sizeof(seq_t));

        /* loop over multiplicities j */
        for (idx_t j = 0; j <= max_j; ++j) {
            seq_t coeff = binom(T, j);
            if (coeff == 0)
                continue;          /* should not happen */

            idx_t shift = j * T;
            if (shift > n)
                break;

            idx_t limit = n - shift;
            for (idx_t i = 0; i <= limit; ++i) {
                if (dp[i] == 0)
                    continue;
                idx_t idx = i + shift;
                newdp[idx] = ADD128(newdp[idx], MUL128(dp[i], coeff));
            }
        }

        /* swap dp and newdp for the next factor */
        seq_t *tmp = dp;
        dp = newdp;
        newdp = tmp;
    }

    seq_t result = dp[n];
    free(dp);
    free(newdp);
    return result;
}
